fn find_peak(a:[*]const i64,lo:usize,hi:usize)i64{const m=(hi-lo)/2;const l=a[lo+m-1];const c=a[lo+m];const r=a[lo+m+1];if(c>l and c>r)return c;if(l<r){const start=if(m==2)m-1 else m;return find_peak(a,lo+start,hi);}const end=if(m==2)m+1 else m;return find_peak(a,lo,lo+end);}
export fn peak(v:[*c]const i64,n:usize)i64{if(v==null or n<4 or n>65 or v[0]<3 or v[0]>64 or n!=@as(usize,@intCast(v[0]))+1)return -1;const len:usize=@intCast(v[0]);for(0..len)|i|if(v[i+1]<-1000000 or v[i+1]>1000000)return -1;var p:usize=1;while(p<len-1 and v[p+1]>v[p]){p+=1;}if(p==1 or p>=len-1)return -1;for(p..len-1)|i|if(v[i+2]>=v[i+1])return -1;return find_peak(v+1,0,len); }
